insert into woerter (slug, wort, artikel, ipa, wortart, kategorie, definition, bedeutungen, beispiel) values
  ('aum-scheabm-hockn', 'aum Scheabm hockn', '', '', '', 'Wiener Sprüche, die sitzen!', 'auf dem Scherben hocken', '[{"kategorie": "wörtlich", "text": "\"auf dem Topf sitzen\""}, {"kategorie": "allg., scherzhaft für", "text": "\"auf dem Klo sitzen\", \"auf der Toilette sein\", \"auf dem Porzellanthron sitzen\", \"aum [[Heisl]] hockn\""}, {"kategorie": "fig.", "text": "\"auf einem Scherbenhaufen sitzen\", \"in der Klemme sitzen\", \"im Arsch sein\""}]'::jsonb, 'Dea hockd jetzd schoo a Dreiviadlschdund aum Scheabm - maansd, soi ma noochschaun?'),
  ('dea-hockd-jetzd-schoo-a-dreiviadlschdund-aum-scheabm-maansd-soi-ma-noochschaun', 'Dea hockd jetzd schoo a Dreiviadlschdund aum Scheabm - maansd, soi ma noochschaun?', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der hockt jetzt schon eine Dreiviertelstunde auf dem Scherben - meinst, sollen wir nachschauen?', '[{"kategorie": "wörtlich", "text": "\"Der sitzt jetzt schon eine Dreiviertelstunde auf dem Töpfchen - was meinst du, sollen wir nachschauen gehen?\"  2. \"Der ist jetzt schon seit 45 Minuten auf der Toilette – sollen wir mal nachsehen?\"  3. \"Der hat sich auf dem Porzellanthron häuslich eingerichtet – jetzt sind schon 45 Minuten vergangen, sollten wir da nicht mal nachschauen gehen?\""}]'::jsonb, 'aum Scheabm hockn'),
  ('frau-weg-goeoed-fuat-i-hock-aum-scheabm', 'Frau weg, Gööd fuat - I hock aum Scheabm!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Frau weg, Geld fort - ich hock auf''m Scherben!', '[{"kategorie": "wörtlich", "text": "\"Frau weg, Geld fort - ich hock auf ''nem Scherbenhaufen!\"  2. \"Frau weg, Geld fort - ich bin im Arsch!\"  3. \"Frau weg, Geld fort – nur noch Scherben unterm Hintern!\""}]'::jsonb, 'aum Scheabm hockn'),
  ('des-scheazl-is-heid-bsundas-guad-duachzoong-nimms-fias-gulasch-daunn-wiads-softig', 'Des Scheazl is heid bsundas guad duachzoong - nimms fias Gulasch, daunn wiads softig!', '', '', '', 'Wiener Fleischhauer-Slang', 'Das Scherzl ist heut besonders gut durchzogen - nimm''s fürs Gulasch, dann wird''s saftig!', '[{"kategorie": "wörtlich", "text": "\"Das Scherzl ist heute besonders schön marmoriert – für ein saftiges Gulasch genau das Richtige!\"  2. \"Dieses Teilstück vom Rind ist heute besonders gut durchzogen - ideal für ein Gulasch, wenn du''s saftig haben willst!\"  3. \"Dieses Rindfleischstück ist besonders gleichmäßig durchzogen und eignet sich hervorragend für ein saftiges Gulasch!\""}]'::jsonb, ''),
  ('des-scheazal-is-heid-bsundas-guad-duachzoong-nimms-fias-gulasch-daunn-wiads-softig', 'Des Scheazal is heid bsundas guad duachzoong - nimms fias Gulasch, daunn wiads softig!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Das Scherzerl ist heut besonders gut durchzogen - nimm''s fürs Gulasch, dann wird''s saftig!', '[{"kategorie": "", "text": "\"Das Scherzerl ist heute besonders schön marmoriert – für ein saftiges Gulasch genau das Richtige!\"  2. \"Dieses Teilstückchen vom Rind ist heute besonders gut durchzogen - ideal für ein Gulasch, wenn du''s saftig haben willst!\"  3. \"Dieses Rindfleischstückchen ist besonders gleichmäßig durchzogen und eignet sich hervorragend für ein saftiges Gulasch!\""}]'::jsonb, ''),
  ('gimma-des-scheazl-vom-leewakaas-des-min-dickn-fettn-gruschpae', 'Gimma des Scheazl vom Leewakaas - des min dickn, fettn Gruschpä!', '', '', '', 'Wiener Würstelstandjargon', 'Gib mir das Scherzl vom Leberkäs - das mit dem dicken, fetten Kruspel!', '[{"kategorie": "wörtlich", "text": "\"Gib mir den Anschnitt vom Leberkäse - mit der dicken, fetten Kruste!\"  2. Ich hätte gern das Endstück vom Leberkäse – das mit der dicken, schön gebräunten Kruste!  3. Wenn ich das dicke Randstück krieg, bin ich ein ganzer Mensch - Leberkäse nur mit Kruste, eh klar!"}]'::jsonb, ''),
  ('gimma-des-scheazal-vom-leewakaas-des-min-dickn-fettn-gruschpae', 'Gimma des Scheazal vom Leewakaas - des min dickn, fettn Gruschpä!', '', '', '', 'Wiener Fleischhauer-Slang', 'Gib mir das Scherzerl vom Leberkäs - das mit dem dicken, fetten Kruspel!', '[{"kategorie": "wörtlich", "text": "\"Gib mir den Anschnitt vom Leberkäse - mit der dicken, fetten Kruste!\"  2. Ich hätte gern das Endstück vom Leberkäse – das mit der dicken, schön gebräunten Kruste!  3. Wenn ich das dicke Randstück krieg, bin ich ein ganzer Mensch - Leberkäse nur mit Kruste, eh klar!"}]'::jsonb, ''),
  ('a-oogscheazlda-vom-neina-is-imma-braundgfaealich', 'A Oogscheazlda vom Neina is imma braundgfäalich!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Ein abgerissenes Scherzl vom Neuner ist immer brandgefährlich!', '[{"kategorie": "wörtlich", "text": "\"Ein Flatterball vom Mittelstürmer ist immer brandgefährlich!\"  2. Ein abgerissener Ball vom Mittelstürmer – wirkt harmlos, ist aber nicht ohne!  3. Ein verunglückter Ball vom Neuner – aber gerade das macht den Schuss so unberechenbar!"}]'::jsonb, ''),
  ('a-oogrissans-scheazal-vom-neina-schaud-hoamlos-aus-is-owa-braundgfaealich', 'A oogrissans Scheazal vom Neina - schaud hoamlos aus, is owa braundgfäalich!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Ein abgerissenes Scherzl vom Neuner – schaut harmlos aus, ist aber brandgefährlich!', '[{"kategorie": "wörtlich", "text": "\"Ein typischer Flatterball vom Mittelstürmer – schaut harmlos aus, ist aber brandgefährlich!\"  2. Ein abgerissener Ball vom Mittelstürmer – wirkt harmlos, ist aber nicht ohne!  3. Ein verunglückter Ball vom Neuner – aber gerade das macht den Schuss so unberechenbar!"}]'::jsonb, ''),
  ('si-a-scheazl-ooschneidn-kennan', 'si a Scheazl ooschneidn kennan', '', '', '', 'Wiener Sprüche, die sitzen!', 'sich ein Scherzel abschneiden können', '[{"kategorie": "wörtlich", "text": "\"sich eine Scheibe von jemandem/etwas abschneiden können\""}, {"kategorie": "fig.", "text": "sich ein Beispiel an jemandem/etwas nehmen können"}, {"kategorie": "", "text": "sich jemanden/etwas zum Vorbild nehmen können"}]'::jsonb, ''),
  ('si-a-scheazal-ooschneidn-kennan', 'si a Scheazal ooschneidn kennan', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'sich ein Scherzel abschneiden können', '[{"kategorie": "wörtlich", "text": "\"sich eine Scheibe von jemandem/etwas abschneiden können\""}, {"kategorie": "fig.", "text": "sich ein Beispiel an jemandem/etwas nehmen können"}, {"kategorie": "", "text": "sich jemanden/etwas zum Vorbild nehmen können"}]'::jsonb, ''),
  ('sei-vooda-hackld-wiara-pfead-von-dem-kennd-si-da-bua-a-scheazl-ooschneidn', 'Sei Vooda hackld wiara Pfead - von dem kennd si da Bua a Scheazl ooschneidn!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Sein Vater hackelt wie ein Pferd - von dem könnte sich der Bub ein Scherzel abschneiden!', '[{"kategorie": "wörtlich", "text": "\"Sein Vater schuftet wie ein Pferd - von dem könnte sich der Junge ''ne Scheibe abschneiden!\"  2. Sein Vater rackert unermüdlich – daran könnte sich der Sohn durchaus ein Beispiel nehmen!  3. Wie sein Vater sich reinhängt, ist bemerkenswert – den könnte sich der Junge ruhig zum Vorbild nehmen!"}]'::jsonb, 'si a Scheazl ooschneidn kennan'),
  ('sei-vooda-hackld-wiara-pfead-von-dem-kennd-si-da-bua-a-scheazal-ooschneidn', 'Sei Vooda hackld wiara Pfead - von dem kennd si da Bua a Scheazal ooschneidn!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Sein Vater hackelt wie ein Pferd - von dem könnte sich der Bub ein Scherzerl abschneiden!', '[{"kategorie": "wörtlich", "text": "\"Sein Vater schuftet wie ein Pferd - von dem könnte sich der Junge ''ne Scheibe abschneiden!\"  2. Sein Vater rackert unermüdlich – daran könnte sich der Sohn durchaus ein Beispiel nehmen!  3. Wie sein Vater sich reinhängt, ist bemerkenswert – den könnte sich der Junge ruhig zum Vorbild nehmen!"}]'::jsonb, ''),
  ('ea-kenntad-si-a-scheazl-von-eam-oschneidn', 'Ea kenntad si a Scheazl von eam oschneidn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Er könnte sich ein Scherzel von ihm abschneiden!', '[{"kategorie": "wörtlich", "text": "\"Er könnte sich eine Scheibe von ihm abschneiden!\"  2. Er könnte sich an ihm ein Beispiel nehmen!  3. Er könnte sich ihn zum Vorbild nehmen!"}]'::jsonb, ''),
  ('ea-hod-sei-scheazl-ookriagd', 'Ea hod sei Scheazl ookriagd!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Er hat sein Scherzel abbekommen!', '[{"kategorie": "wörtlich", "text": "\"Er hat seine dicke Scheibe abbekommen!\"  2. (fig.) Er hat sein Fett abbekommen!  2. Er hat bekommen, was er verdient!"}]'::jsonb, ''),
  ('wems-scheazl-owareissn', 'wems Scheazl owareissn', '', '', '', 'Wiener Sprüche, die sitzen!', 'jemandem das Scherzel runterreißen', '[{"kategorie": "wörtlich", "text": "\"jemandem ''ne Scheibe runterreißen\""}, {"kategorie": "fig.", "text": "\"jemandem den Kopf abreißen\""}, {"kategorie": "", "text": "\"jemanden zur Schnecke machen\""}, {"kategorie": "", "text": "\"jemanden [[zusammenstauchen]]\""}]'::jsonb, 'Dea wiad da s''Scheazl scho ned owareissn, waunnsd eams gscheid eakläasd!'),
  ('dea-wiad-da-s-scheazl-scho-ned-owareissn-waunnsd-eams-gscheid-eaklaeasd', 'Dea wiad da s''Scheazl scho ned owareissn, waunnsd eams gscheid eakläasd!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der wird dir das Scherzel schon nicht runterreißen, wenn du es ihm gescheit erklärst!', '[{"kategorie": "wörtlich", "text": "\"Der wird dir schon nicht den Kopf abreißen, wenn du es ihm gescheit erklärst!\"  2. Der wird dir schon nicht gleich den Hals umdrehen, wenn du es ihm ordentlich verklickerst!  3. Der wird dich schon nicht gleich zur Schnecke machen, wenn du''s clever verpackst!"}]'::jsonb, 'wems Scheazl owareissn'),
  ('wems-scheazl-ooreissn', 'wems Scheazl ooreissn', '', '', '', 'Wiener Sprüche, die sitzen!', 'jemandem das Scherzel abreißen', '[{"kategorie": "wörtlich", "text": "\"jemandem ein Stück aus dem Leib reißen\""}, {"kategorie": "", "text": "\"jemandem ein ordentliches Eck rausreißen\""}, {"kategorie": "", "text": "\"jemandem den Kopf abreißen\""}, {"kategorie": "", "text": "\"jemandem den Hals umdrehen\""}, {"kategorie": "", "text": "jemanden [[zusammenstauchen]]"}]'::jsonb, 'Dea wiad da s''Scheazl scho ned ooreissn, waunnsd eams gscheid eakläasd!'),
  ('dea-wiad-da-s-scheazl-scho-ned-ooreissn-waunnsd-eams-gscheid-eaklaeasd', 'Dea wiad da s''Scheazl scho ned ooreissn, waunnsd eams gscheid eakläasd!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der wird dir das Scherzel schon nicht abreißen, wenn du es ihm gescheit erklärst!', '[{"kategorie": "wörtlich", "text": "\"Der wird dir schon nicht den Kopf abreißen, wenn du es ihm gescheit erklärst!\"  2. Der wird dir nicht gleich ein Eck rausreißen, wenn du es ihm ordentlich verklickerst!  3. Der wird dir schon nicht den Hals umdrehen, wenn du''s clever verpackst!"}]'::jsonb, 'wems Scheazl ooreissn'),
  ('im-vagleich-zum-moogan-meisl-is-des-schuitascheazl-duachzoogana-und-no-gschmackiga', 'Im Vagleich zum Moogan Meisl is des Schuitascheazl duachzoogana und no gschmackiga!', '', '', '', 'Wiener Fleischhauer-Slang', 'Im Vergleich zum Mageren Meisel ist das Schulterscherzel durchzogener und noch g''schmackiger!', '[{"kategorie": "wörtlich, Fleischerjargon", "text": "\"Im Vergleich zum Mageren Meisel ist das Schulterscherzel etwas durchzogener und noch geschmackvoller!\"  2. Im Unterschied zum Mageren Meisel enthält das Schulterscherzel mehr Fett und überzeugt dadurch mit vollem Geschmack!  3. Das Schulterscherzel ist stärker marmoriert als das magere Meisl und deshalb noch geschmackvoller!"}]'::jsonb, ''),
  ('heit-haed-i-a-frischs-buugscheazl-peafekt-fias-gulasch-ned-zu-seenig-schee-duachzoong', 'Heit häd I a frischs Buugscheazl - peafekt fias Gulasch, ned zu seenig, schee duachzoong!', '', '', '', 'Wiener Fleischhauer-Slang', 'Heut hätt ich ein frisches Bugscherzl – perfekt fürs Gulasch, nicht zu sehnig, schön durchzogen!', '[{"kategorie": "wörtlich, Fleischerjargon", "text": "\"Heute habe ich ein frisches Stück aus der Rinderschulter – ideal für Gulasch, schön marmoriert und nicht zu sehnig!\"  2. Frisch eingetroffen: ein tolles Schulterstück vom Rind – wunderbar durchzogen, perfekt zum Schmoren!  3. Ich hätte heute ein wunderbar zartes Stück aus dem Wadschinken – genau das Richtige für ein kräftiges Gulasch!"}]'::jsonb, ''),
  ('mit-an-hueuefalscheazl-kaunnst-sogoa-an-vegaana-bekean-vorausgsetzd-ea-schmeckd-no-wos', 'Mit an Hüüfalscheazl kaunnst sogoa an Vegaana bekean - vorausgsetzd, ea schmeckd no wos!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Mit einem Hüferlscherzel kannst du sogar einen Veganer bekehren – vorausgesetzt, er schmeckt noch was!', '[{"kategorie": "wörtlich", "text": "\"Mit einem zarten Rinderhüftstück kannst du sogar einen Veganer bekehren – vorausgesetzt, er schmeckt noch was!\"  2. Ein zartes Hüferlscherzl – und selbst der militanteste Veganer fängt an zu kauen!  3. Mit einem saftigen Hüferlscherzl bringst du sogar jeden Körndlfresser zum Umdenken – sofern er noch was schmeckt!"}]'::jsonb, ''),
  ('wea-wos-bsundas-suachd-und-kaa-filee-zoin-wueue-fia-den-is-des-hueuefalschwanzal-genau-des-richtige', 'Wea wos Bsundas suachd und kaa Filee zoin wüü, fia den is des Hüüfalschwanzal genau des Richtige!', '', '', '', 'Wiener Fleischhauer-Slang', 'Wer was Besonderes sucht, aber kein Filet zahlen will, für den ist das Hüferlschwanzerl genau das Richtige!', '[{"kategorie": "wörtlich", "text": "\"Wer was Besonderes sucht, aber kein Filet zahlen will, für den ist das zarte Schnittstück aus der Rinderoberschale genau das Richtige!\"  2. Fein wie ein Filet, aber deutlich günstiger – das Hüferlschwanzerl ist ein Geheimtipp für Genießer!  3. Viel Geschmack, wenig Preis: Das Hüferlschwanzerl überzeugt, ohne das Börserl übermäßig zu belasten!"}]'::jsonb, ''),
  ('nimm-fias-stejk-liawa-a-beiriad-ois-a-filee-mea-gschmock-und-trotzdem-zoat', 'Nimm fias Stejk liawa a Beiriad ois a Filee - mea Gschmock und trotzdem zoat!', '', '', '', 'Wiener Fleischhauer-Slang', 'Nimm fürs Steak lieber ein Beiried statt ein Filet – mehr Geschmack und trotzdem zart!', '[{"kategorie": "wörtlich", "text": "\"Nimm fürs Steak lieber ein Zwischenrippenstück als ein Filet – mehr Geschmack und trotzdem zart!\"  2. Beiried ist die bessere Wahl für Steakliebhaber: intensiver im Geschmack, dabei angenehm weich!  3. Wer beim Steak Wert auf Aroma legt, greift zum Beiried statt zum Filet!"}]'::jsonb, ''),
  ('weisses-scheazl', 'Weisses Scheazl', 'das', '', '', 'Wiener Fleischhauer-Slang', 'Weißes Scherzl', '[{"kategorie": "wörtlich", "text": "\"Weißes Scherzel\" (mageres Kochfleischstück aus dem hinteren Rinderschlögel)"}, {"kategorie": "Fleischhauerjargon", "text": "\"Semerrolle\",  \"Schnittstück vom hinteren Teil des Rinderschlögels\", \"mageres Siedefleischstück aus der Schale\""}]'::jsonb, 'Des Weisse Scheazl hod a gleichmäässige Faasa und is extrem sauwa zum Schneidn!'),
  ('des-weisse-scheazl-hod-a-gleichmaeaessige-faasa-und-is-extrem-sauwa-zum-schneidn', 'Des Weisse Scheazl hod a gleichmäässige Faasa und is extrem sauwa zum Schneidn!', '', '', '', 'Wiener Fleischhauer-Slang', 'Das Weiße Scherzel hat eine gleichmäßige Faser und ist extrem sauber zum Schneiden!', '[{"kategorie": "wörtlich", "text": "\"Die Semerrolle hat eine gleichmäßige Faser und lässt sich extrem sauber schneiden!\"  2. Das Weiße Scherzel zeichnet sich durch seine feine, gleichmäßige Faserstruktur aus und ist sehr gut zu portionieren!  3. Die Semerrolle – oder das Weiße Scherzel – ist ein echtes Vorzeigestück, wenn’s um Zartheit, Struktur und Schneidequalität geht!"}]'::jsonb, 'Weisses Scheazl'),
  ('do-wiad-an-sauschiach', 'Do wiad an sauschiach!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Da wird einem sauschirch!', '[{"kategorie": "wörtlich", "text": "\"Da wird einem sauschlecht!\"  2. Da wird einem sauübel!  3. Da wird einem total ungut!"}]'::jsonb, ''),
  ('den-sei-oide-is-sauschiach', 'Den sei Oide is sauschiach!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Die Alte von dem ist sauschirch!', '[{"kategorie": "wörtlich", "text": "\"Seine Alte ist potthässlich!\"  2. Die Frau von dem schaut echt grottig aus!  3. Seine Alte ist echt zum Davonlaufen!"}]'::jsonb, ''),
  ('heit-hods-a-schiachs-weeda', 'Heit hods a schiachs Weeda!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Heute hat es ein schirches Wetter!', '[{"kategorie": "wörtlich", "text": "\"Heute ist das Wetter schlecht!\"  2. Richtig grindiges Wetter heute!  3. Das Wetter ist heute miserabel!"}]'::jsonb, ''),
  ('heit-hods-a-sauschiachs-weeda', 'Heit hods a sauschiachs Weeda!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Heute hat es ein sauschirches Wetter!', '[{"kategorie": "wörtlich", "text": "\"Heute ist das Wetter sauschlecht!\"  2. Richtig grindiges Wetter heute!  3. Das Wetter ist heute hundsmiserabel!  4. Was für ein grässliches Schmuddelwetter heute!"}]'::jsonb, ''),
  ('waunnsd-ma-de-marii-ned-zruckgibsd-weari-schiach', 'Waunnsd ma de Marii ned zruckgibsd, weari schiach!', '', '', '', 'Wiener Gaunersprache', 'Wenn du mir die Marie nicht zurückgibst, werde ich schirch!', '[{"kategorie": "wörtlich", "text": "\"Wenn du mir das Geld nicht zurückgibst, werde ich bitterböse!\"  2. Wenn du mir die Moneten nicht zurückgibst, werde ich richtig sauer!  3. Wenn du mir den [[Flieder]] nicht zurückgibst, wirst du sehen, wie böse ich werden kann!"}]'::jsonb, ''),
  ('waunnsd-di-ned-entschuidigst-weari-sauschiach', 'Waunnsd di ned entschuidigst, weari sauschiach!', '', '', '', 'Wiener Gaunersprache', 'Wenn du dich nicht entschuldigst, werde ich sauschirch!', '[{"kategorie": "wörtlich", "text": "\"Wenn du dich nicht entschuldigst, werde ich sauwütend!\"  2. Wenn da keine Entschuldigung kommt, raste ich richtig aus!  3. Wenn du dich nicht entschuldigst, flippe ich komplett aus!"}]'::jsonb, ''),
  ('a-richtig-grindichs-weeda-heit', 'A richtig grindichs Weeda heit!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Ein richtig grindiges Wetter heute!', '[{"kategorie": "wörtlich", "text": "\"Richtig schlechtes Wetter heute!\"  2. Was für ein Schmuddelwetter heute!  3. So ein nasskaltes Gatschwetter heute!  4. [[Heit]] hods a sauschiachs Weeda!"}]'::jsonb, ''),
  ('a-richtig-sudrichs-weeda-heit', 'A richtig sudrichs Weeda heit!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Ein richtig sudriges Wetter heute!', '[{"kategorie": "wörtlich", "text": "\"Richtig schlechtes Wetter heute!\"  2. Was für ein feuchtkaltes Schmuddelwetter heute!  3. So ein nasskaltes Gatschwetter heute!  4. [[Heit]] hods a sauschiachs Weeda!"}]'::jsonb, ''),
  ('do-wiad-an-schiach', 'Do wiad an schiach!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Da wird einem schirch!', '[{"kategorie": "wörtlich", "text": "\"Da wird einem schlecht!\"  2. Da wird einem übel!  3. Da kommt einem das Grauen!"}]'::jsonb, ''),
  ('schiach-wia-da-zins', 'schiach wia da Zins', '', '', '', 'Wiener Sprüche, die sitzen!', 'schirch wie der Zins', '[{"kategorie": "wörtlich", "text": "\"hässlich wie wie die Mietzinszahlung am Monatsbeginn\""}, {"kategorie": "allg.", "text": "hässlich wie die Nacht"}, {"kategorie": "fig.", "text": "über die Maßen schlimm, übel bis zum Gehtnichtmehr, schwer zu ertragen"}]'::jsonb, ''),
  ('so-a-kraunkheid-is-schiach-wia-da-zins', 'So a Kraunkheid is schiach wia da Zins!', '', '', '', 'Krank & kuriert auf Wienerisch', 'So eine Krankheit ist schirch wie der Zins!', '[{"kategorie": "wörtlich", "text": "\"So eine Krankheit ist so schlimm wie wie die Mietzinszahlung am Monatsbeginn!\"  2. So eine Krankheit ist genauso übel wie die Miete am Ersten!  3. Die Krankheit ist genauso willkommen wie die Miete am Monatsanfang!"}]'::jsonb, 'schiach wia da Zins'),
  ('schiach-wia-de-nocht', 'schiach wia de Nocht', '', '', '', 'Wiener Sprüche, die sitzen!', 'schirch wie die Nacht', '[{"kategorie": "wörtlich", "text": "\"hässlich wie die Nacht\" (von Personen, Tieren oder Gegenständen)"}, {"kategorie": "allg.", "text": "abgrundtief hässlich, nicht zum Anschauen, zum Davonlaufen"}, {"kategorie": "fig.", "text": "über die Maßen schlimm, übel bis zum Gehtnichtmehr, schwer zu ertragen, arg wie die Pest, [[schiach]] wia da Zins"}]'::jsonb, 'Kraunk sei is schiach wia de Nocht!'),
  ('kraunk-sei-is-schiach-wia-de-nocht', 'Kraunk sei is schiach wia de Nocht!', '', '', '', 'Krank & kuriert auf Wienerisch', 'Krank zu sein ist schirch wie die Nacht!', '[{"kategorie": "wörtlich", "text": "\"Krank zu sein ist bitter wie die dunkle Nacht!\"  2. Eine Krankheit lässt sich genauso schwer ertragen wie ''ne dunkle Nacht!  3. Krank zu sein ist, als ginge man durch eine lange dunkle Nacht - nur Kälte und Grau!"}]'::jsonb, 'schiach wia de Nocht'),
  ('dea-hund-is-schiach-wia-de-nocht-owa-wenigstns-boeoeda-ned', 'Dea Hund is schiach wia de Nocht, owa wenigstns bööda ned!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Der Hund ist schirch wie die Nacht, aber wenigstens bellt er nicht!', '[{"kategorie": "wörtlich", "text": "\"Der Hund ist hässlich wie die Nacht, aber wenigstens bellt er nicht!\"  2. Der Hund ist zwar hässlich wie die Sünde, aber wenigstens still!  3. Der Hund sieht zwar furchtbar aus, aber er macht wenigstens keinen Lärm!"}]'::jsonb, 'schiach wia de Nocht'),
  ('eana-bua-is-a-echts-schiachal', 'Eana Bua is a echts Schiachal!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Ihr Bub ist ein echtes Schircherl!', '[{"kategorie": "wörtlich", "text": "\"Ihr Bub ist alles andere als ein Hingucker!\"  2. Ihr Bub ist wirklich ein hässliches Entlein!  3. Ihr Bub ist nicht zum Anschauen!"}]'::jsonb, ''),
  ('da-puudl-is-a-schiachal-owa-iagendwia-siass', 'Da Puudl is a Schiachal, owa iagendwia siass!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der Pudel ist ein Schircherl, aber irgendwie süß!', '[{"kategorie": "wörtlich", "text": "\"Der Pudel ist so hässlich, dass er irgendwie schon wieder süß ist!\"  2. So unansehnlich der Hund auch ist, man kann ihn trotzdem liebhaben!  3. Der Pudel ist äußerlich nicht der Hübscheste, aber dafür umso niedlicher!"}]'::jsonb, ''),
  ('mei-mau-woa-scho-imma-a-schiachal-owa-wenigstns-ka-ungeheia', 'Mei Mau woa scho imma a Schiachal, owa wenigstns ka Ungeheia!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Mein Mann war schon immer ein Schircherl, aber wenigstens kein Ungeheuer!', '[{"kategorie": "wörtlich", "text": "\"Mein Mann war äußerlich noch nie der Hübscheste, aber wenigstens ist er lieb und nett!\"  2. Mein Mann war noch nie ein Schönling, aber menschlich ist er okay!  3. Mein Mann war schon immer [[schirch]] – aber ein Ungeheuer war er nie!"}]'::jsonb, ''),
  ('mit-dem-schiachal-taeu-i-schoo-zwanzg-joa-es-bett', 'Mit dem Schiachal täu I schoo zwanzg Joa es Bett!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Mit diesem Schircherl teile ich schon zwanzig Jahre das Bett!', '[{"kategorie": "wörtlich", "text": "\"Mit diesem Rumpelstilzchen teile ich schon zwanzig Jahre das Bett!\"  2. Mit meinem Krokodil lieg ich schon zwei Jahrzehnte lang im selben Bett!  3. Zwanzig Jahre schlaf ich schon neben diesem Schrumpelgeier im selben Bett!"}]'::jsonb, ''),
  ('du-schiachpeachtn-du-sauschiache-du', 'Du Schiachpeachtn, du sauschiache du!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Du Schirchperchte, du sauschirche du!', '[{"kategorie": "wörtlich", "text": "\"Du hässliche Vogelscheuche, du sauhässliche du!\"  2. \"Du grindiges Höllenweib, du saugrindiges du!\"  3. \"Du böse, schirche Sauhexe, du!\""}]'::jsonb, ''),
  ('bei-uns-im-duaf-woonan-lauta-schiachpeachtn', 'Bei uns im Duaf woonan lauta Schiachpeachtn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Bei uns im Dorf wohnen lauter Schirchperchten!', '[{"kategorie": "wörtlich", "text": "\"Bei uns im Dorf wohnen lauter hässliche Frauen!\"  2. Bei uns im Dorf sind die Weiber nicht grad fürs Theater gemacht – höchstens für''n Maskenball!  3. Bei uns im Dorf sind die Frauen alle nicht schön, eher naturbelassen!"}]'::jsonb, ''),
  ('waaradn-de-weiba-olle-peachtn-daed-bei-uns-de-raunocht-a-gaunzes-joa-laung-dauan', 'Waaradn de Weiba olle Peachtn, däd bei uns de Raunocht a gaunzes Joa laung dauan!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Wären die Weiber alle Perchten, würde die Raunacht bei uns ein ganzes Jahr lang dauern!', '[{"kategorie": "wörtlich", "text": "\"Wenn alle Frauen wie Perchten aussähen, wär das ganze Jahr Raunacht!\"  2. Gäb’s bei uns nur [[Perchtengesichter]], würd der Krampus freiwillig auswandern!  3. Wären alle Weiber Teufelshexen, würd sich der Nebel nie verziehen!"}]'::jsonb, ''),
  ('vua-de-schoenpeachtn-fiachd-si-kaana-nua-vua-de-schiachpeachtn', 'Vua de Schönpeachtn fiachd si kaana, nua vua de Schiachpeachtn!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Vor den Schönperchten fürchtet sich keiner, nur vor den Schirchperchten!', '[{"kategorie": "wörtlich", "text": "\"Vor den schönen Perchten fürchtet sich niemand - nur vor den Schirchperchten!\"  2. Niemand hat Angst vor den schönen Perchten – nur vor den hässlichen Teufelsgestalten!  3. Vor den lieben Perchten hat keiner Angst – aber vor den wilden Höllengestalten flüchtet sogar der Hund unter den Tisch!"}]'::jsonb, ''),
  ('de-schoenpeachtn-is-nett-de-schiachpeachtn-bringt-s-gfrett', 'De Schönpeachtn is nett, de Schiachpeachtn bringt''s Gfrett!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Die Schönperchte ist nett, die Schirchperchte bringt''s Gfrett!', '[{"kategorie": "wörtlich", "text": "\"Die Schönperchte bringt Segen, die Schirchperchte den Regen!\"  2. Die Schönpercht macht Freud, die Schirchpercht bringt Leid!  3. Die Schönperchten streicheln d’Leut, die Schiachperchten prügeln sie aus’m Winter!"}]'::jsonb, ''),
  ('de-weiba-in-unsan-duaf-kaunnst-bestnfois-fian-peachtnlauf-aumoeoedn', 'De Weiba in unsan Duaf kaunnst bestnfois fian Peachtnlauf aumöödn!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Die Weiber in unserem Dorf kannst du bestenfalls für den Perchtenlauf anmelden!', '[{"kategorie": "wörtlich", "text": "\"Die Frauen in unserem Dorf kannst du bestenfalls zum Perchtenlauf anmelden!\"  2. Die Damen bei uns im Dorf könnten glatt als [[Schirchperchten]] durchgehen – ganz ohne Maske!  3. In unserem Dorf die [[Perchtengesichter]] nicht für den Laufsteg gemacht - sondern nur für die [[Raunacht]]!"}]'::jsonb, ''),
  ('de-koeoenarin-haedad-a-supa-figua-owa-leida-hods-a-peachtngsicht', 'De Köönarin hädad a supa Figua, owa leida hods a Peachtngsicht!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Die Kellnerin hätte eine super Figur, aber leider hat sie ein Perchtengesicht!', '[{"kategorie": "wörtlich", "text": "\"Die Kellnerin hätte eine super Figur, aber leider hat sie eine Raunachtsvisage!\"  2. Die Kellnerin hat echt eine tolle Figur – schade nur ums Gesicht!  3. A Figur wia a Göttin – und a G’schau wia a Krampus!"}]'::jsonb, ''),
  ('a-figua-wiara-goettin-und-a-gschau-wiara-krampus', 'A Figua wiara Göttin – und a Gschau wiara Krampus!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Eine Figur wie eine Göttin - und ein Gschau wie ein Krampus!', '[{"kategorie": "wörtlich", "text": "\"Eine Figur wie die Venus - und eine Visage wie der Krampus!\"  2. Der Leib wie eine Venus, doch das Gesicht wie eine Perchte!  3. Sie hat die Figur einer Schönheitskönigin - schade nur ums Gesicht!"}]'::jsonb, ''),
  ('a-figua-wiara-goettin-und-a-gschau-wiara-peachtn', 'A Figua wiara Göttin – und a Gschau wiara Peachtn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Eine Figur wie eine Göttin - und ein Gschau wie eine Perchte!', '[{"kategorie": "wörtlich", "text": "\"Eine Figur wie die Venus - und eine Visage wie ''ne Perchte!\"  2. Der Leib wie eine Venus, doch das Gesicht wie ein Krampus!  3. Sie hat die Figur einer Schönheitskönigin - schade nur ums Gesicht!"}]'::jsonb, ''),
  ('a-leib-wiara-venus-und-a-gsicht-wiara-krampus', 'A Leib wiara Venus, und a Gsicht wiara Krampus!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Ein Leib wie eine Venus - und ein Gesicht wie ein Krampus!', '[{"kategorie": "wörtlich", "text": "\"Eine Figur wie eine Venus - und eine Visage wie ein Krampus!\"  2. Eine Figur wie eine Göttin - und ein Gschau wie ''ne Perchte!  3. Echt tolle Figur - schade nur ums Gesicht!"}]'::jsonb, ''),
  ('a-leib-wiara-venus-und-a-gsicht-wiara-peachtn', 'A Leib wiara Venus, und a Gsicht wiara Peachtn!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Ein Leib wie eine Venus - und ein Gesicht wie eine Perchte!', '[{"kategorie": "wörtlich", "text": "\"Eine Figur wie eine Venus - und eine Visage wie eine Perchte!\"  2. Eine Figur wie eine Göttin - und ein Gschau wie ein Krampus!  3. Echt tolle Figur - schade nur ums Gesicht!"}]'::jsonb, ''),
  ('waunn-da-schaeaewade-de-schdiang-owekraeud-klimpan-seine-baana-wia-loose-schraufn-in-an-weakzeigkistl', 'Waunn da Schääwade de Schdiang owekräud, klimpan seine Baana wia loose Schraufn in an Weakzeigkistl!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Wenn der Schepperte die Stiegen runterkräult, klimpern seine Gebeine wie lose Schrauben in ''ner Werkzeugkiste!', '[{"kategorie": "wörtlich", "text": "\"Wenn dieses wandelnde Gerippe die Stiegen runterkommt, scheppern seine Knochen wie lose Schrauben in der Werkzeugkiste!\"  2. \"Wenn der Knochenmann die Stiegen runterpoltert, klingt’s wie ''ne Werkzeugkiste ohne Deckel!\"  3. \"Wenn das Klappergestell die Stiegen runterkriecht, hörst du sein Skelett scheppern!\""}]'::jsonb, ''),
  ('du-oida-schaeaewada-schnaeaebrunza', 'Du oida, schääwada Schnääbrunza!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Du alter, schepperter Schneebrunzer!', '[{"kategorie": "wörtlich", "text": "\"Du alter, scheppernder Schneebrunzer!\"  2. \"Du halbverwester Tattergreis!\"  3. \"Du altes, schepperndes [[Heugeigengestell]]!\""}]'::jsonb, ''),
  ('du-oids-schaeaewads-heigeigngschdoeoe', 'Du oids, schääwads Heigeigngschdöö!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Du altes, scheppertes Heugeigengestell!', '[{"kategorie": "wörtlich", "text": "\"Du altes, schepperndes Klappergestell!\"  2. \"Du halbverwester Tattergreis!\"  3. \"Du altes, schepperndes Knochengerüst!\""}]'::jsonb, ''),
  ('do-hods-an-moadstrumm-schaeaewara-gmochd-de-taubm-san-vom-doch-gfloong-und-mia-hods-de-plombn-neich-soatiad', 'Do hods an moadstrumm Schääwara gmochd - de Taubm san vom Doch gfloong und mia hods de Plombn neich soatiad!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Da hat es einen mordstrumm Schepperer gemacht - die Tauben sind vom Dach geflogen und mir hat''s die Plomben neu sortiert!', '[{"kategorie": "wörtlich", "text": "Da hat es einen Riesenschepperer gemacht - die Tauben sind panisch vom Dach geflogen und mir hat''s das Gebiss durchgeschüttelt!\"  2. \"Da war ein mordstrumm Rumpler – die Tauben sind vom Dach geschossen und mir hat’s die Plomben durcheinandergewürfelt!\"  3. \"Da hat’s einen abartigen Knall gegeben – die Tauben sind fluchtartig  abgehauen und mir hat''s den Kiefer neu eingerenkt!"}]'::jsonb, ''),
  ('i-soog-da-gaunz-ealich-mit-dem-schaeaewakostn-foast-entweeda-haam-oda-direkt-ind-statistik', 'I soog da gaunz ealich: Mit dem Schääwakostn foast entweeda haam oda direkt ind Statistik!', '', '', '', 'Wiener Mechaniker-Slang', 'Ich sag dir ganz ehrlich: Mit dem Schepperkasten fährst du entweder heim – oder direkt in die Statistik!', '[{"kategorie": "wörtlich, Mechanikerjargon", "text": "\"Ich sag’s dir frei raus: Mit dieser Klapperkiste kommst du entweder heim – oder direkt in die Unfallstatistik!\"  2. \"Ich sag dir, wie’s ist: Mit dem Hobel schaffst du’s entweder bis vor die Haustür oder direkt in die Unfallakte!\"  3. \"Ganz ehrlich: Mit diesem Fetzenflieger endet deine nächste Fahrt entweder daheim oder unter der Feuerwehrplane!\""}]'::jsonb, ''),
  ('vagiss-sauware-akkoade-dea-schaeaewakostn-wueue-prueuegld-wean', 'Vagiss sauware Akkoade - dea Schääwakostn wüü prüügld wean!', '', '', '', 'Wienerisches aus Musik, Kunst, Kultur & Medien', 'Vergiss saubere Akkorde - dieser Schepperkasten will geprügelt werden!', '[{"kategorie": "wörtlich, Musikerjargon", "text": "\"Vergiss saubere Akkorde - bei dieser Klimperkiste musst du richtig reindreschen!\"  2. \"Das ist kein Klavier für Feinmotorik – bei diesem Schepperkasten musst du richtig reinhauen!\"  3. \"Vergiss saubere Harmonien - dieses Rumpelklavier klingt nur, wenn du ordentlich draufhaust!\""}]'::jsonb, ''),
  ('schaeaewan1', 'schääwan1', '', '', '', 'Grundwortschatz Wienerisch', 'scheppern', '[{"kategorie": "wörtlich", "text": "\"scheppern\" (lautmalerisches Wort, das ein lautes, hartes, klirrend-klapperndes Geräusch nachahmt\")"}, {"kategorie": "allg.", "text": "klappern\",\"rasseln\", \"krachen\", \"klirren\""}, {"kategorie": "fig.", "text": "zittern (vor Angst, Kälte, etc.), bibbern, schlottern, \"am ganzen Leib rappeln\""}]'::jsonb, 'Dea schääwad mit de Baana!'),
  ('schaeaewan-wiara-kluppnsackl', 'schääwan wiara Kluppnsackl', '', '', '', 'Wiener Sprüche, die sitzen!', 'scheppern wie ein Kluppensackel', '[{"kategorie": "wörtlich", "text": "\"scheppern wie ein [[Sackerl]] Wäscheklammern\""}, {"kategorie": "vor Kälte", "text": "\"am ganzen Leib zittern\", \"zittern wie Espenlaub\", \"klappern vor Kälte\", \"zittern bis in die Knochen\""}, {"kategorie": "vor Angst, Gaunerjargon", "text": "\"am ganzen Leib zittern\", \"zittern wie Espenlaub\", \"klappern vor Angst\", \"sich vor Angst fast in die Hose machen\""}]'::jsonb, 'Mia woa so oaschkoid - I hob gschääwad wiara Kluppnsackl!'),
  ('i-hob-gschaeaewad-wiara-kluppnsackl-wiara-de-puffn-aussezoong-hod', 'I hob gschääwad wiara Kluppnsackl, wiara de Puffn aussezoong hod!', '', '', '', 'Wiener Gaunersprache', 'Ich hab gescheppert wie ein Kluppensackl, als er die Puff''n rausgezogen hat!', '[{"kategorie": "wörtlich, Gaunerjargon", "text": "\"Ich hab gezittert wie Espenlaub, als er die Knarre rausholte!\"  2. \"Als er die Waffe zog, hab ich mir vor Angst fast in die Hose geschissen!\"  3. \"Als er die Pistole aus dem Sack holte, hab ich am ganzen Leib gerappelt!\""}]'::jsonb, 'schääwan wiara Kluppnsackl'),
  ('mia-woa-so-oaschkoid-i-hob-gschaeaewad-wiara-kluppnsackl', 'Mia woa so oaschkoid - I hob gschääwad wiara Kluppnsackl!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Mir war so arschkalt - ich hab gescheppert wie ein Kluppensackl!', '[{"kategorie": "wörtlich", "text": "\"Mir war so eiskalt - ich hab gezittert wie Espenlaub!\"  2. \"Mir war saukalt – meine Zähne haben geklappert, meine Knie haben gezittert!\"  3. \"Mir war so scheißkalt, dass ich nur noch am Bibbern war!\""}]'::jsonb, 'schääwan wiara Kluppnsackl'),
  ('dea-schaeaewad-mit-de-baana', 'Dea schääwad mit de Baana!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der scheppert mit den Gebeinen', '[{"kategorie": "wörtlich", "text": "\"Der rasselt mit den Knochen!\"  2. \"Bei dem klappert’s im Gebälk!\"  3. \"Der ist so klapperdürr, dass sein Skelett beim Gehen scheppert!"}]'::jsonb, ''),
  ('dea-schaeaewad-im-gwaund', 'Dea schääwad im Gwaund!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Der scheppert im Gewand', '[{"kategorie": "wörtlich", "text": "\"Der klappert im Gewand!\"  2. \"Seine Knochen rasseln unter dem Gewand!\"  3. \"Der ist nur noch ein klapperdürres Gerippe, das vom Gewand notdürftig zusammengehalten wird!\""}]'::jsonb, ''),
  ('schaeaewan2', 'Schääwan2', 'die', '', '', 'Grundwortschatz Wienerisch', 'Scheppern', '[{"kategorie": "wörtlich", "text": "\"Schepper\" (von [[scheppern]]=\"lautmalerisches Wort, das ein lautes, hartes, klirrend-klapperndes Geräusch nachahmt\")"}, {"kategorie": "mus.", "text": "Schellenrassel (Perkussionsinstrument), Tambourin, Schellenkranz, [[Schääwal]]"}, {"kategorie": "fig., in Bezug auf Personen", "text": "\"Klappergreisin\" (alte, klapperdürre Frau), \"Knochenhexe\" (klapperdürre, böse, alte Frau, deren Knochen beim Gehen scheppern\"), \"Klappergestell\", \"wandelndes Gerippe\", [[alte]] Schachtel, [[Grammel]], [[Schastrommel]]"}]'::jsonb, 'De Knochn von dera oidn Schääwan rassln so laut, dassd nii waassd, obs noo geed oda obs schoo ausaranaundafoid!'),
  ('de-knochn-von-dera-oidn-schaeaewan-rassln-so-laut-dassd-nii-waassd-obs-noo-geed-oda-obs-schoo-ausaranaundafoid', 'De Knochn von dera oidn Schääwan rassln so laut, dassd nii waassd, obs noo geed oda obs schoo ausaranaundafoid!', '', '', '', 'Tod und Sterben auf Wienerisch', 'Die Knochen von dieser alten Scheppern rasseln so laut, dass du nie weißt, ob sie noch geht oder ob sie schon auseinanderfällt!', '[{"kategorie": "wörtlich", "text": "\"Die Knochen dieser Klappergreisin rasseln so laut, dass man nie weiß, ob sie noch geht oder schon auseinanderfällt!\"  2. \"Die Knochen von dieser alten Scheppern klappern so laut, dass selbst der Tod nicht weiß, ob er warten oder aufkehren soll!\"  3. \"So laut rasseln die Knochen von dieser alten Klapperhexe, dass jeder Schritt wie ein Auseinanderbrechen klingt!\""}]'::jsonb, ''),
  ('nimm-im-refraeu-de-schaeaewan-dazua-daunn-heebd-da-gruuf-mea-oo', 'Nimm im Refräu de Schääwan dazua, daunn heebd da Gruuf mea oo!', '', '', '', 'Wienerisches aus Musik, Kunst, Kultur & Medien', 'Nimm im Refrain die Scheppern dazu, dann hebt der Groove mehr ab!', '[{"kategorie": "wörtlich, Musikerjargon", "text": "\"Nimm im Refrain die Schellenrassel dazu, dann hebt der Groove mehr ab!\"   2. \"Leg im Chorus noch Schellen drauf, das zieht den Groove hoch!\"  3. \"Tambourin ab Refrain gibt dem Groove mehr Lift!\""}]'::jsonb, ''),
  ('des-schaeaewal-is-laut-des-bauxal-is-glicklich-und-mia-san-kuaz-vuam-neafnzusaummanbruuch', 'Des Schääwal is laut, des Bauxal is glicklich, und mia san kuaz vuam Neafnzusaummanbruuch!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Das Schepperl ist laut, das Bauxerl ist glücklich, und wir sind kurz vorm Nervenzusammenbruch!', '[{"kategorie": "wörtlich", "text": "\"Die Rassel ist laut, das Baby ist glücklich, und unsere Nerven sind tot!\"  2. \"Die Rassel macht Krach, das Baby ist glücklich – und unsere Nerven sind kaputt!\"  3. \"Die Rassel scheppert, das Baby strahlt, und unsere Nerven sind hinüber!\""}]'::jsonb, ''),
  ('des-schaeaewal-is-sei-easchds-musikinstrument-talent-fia-laeam-is-schoo-do', 'Des Schääwal is sei easchds Musikinstrument - Talent fia Läam is schoo do!', '', '', '', 'Wienerisches aus Musik, Kunst, Kultur & Medien', 'Das Schepperl ist sein erstes Musikinstrument – Talent für Lärm ist schon da!', '[{"kategorie": "wörtlich", "text": "\"Der Schellenkranz ist sein erstes Musikinstrument – Talent für Lärm hat er schon!\"  2. \"Mit dem Schepperl gibt er sein Bühnendebüt – Lautstärke beherrscht er schon!\"  3. \"Musikalischer Einstieg mit dem Tambourin - viel Lärm, wenig Talent!\""}]'::jsonb, ''),
  ('auf-so-aan-schinaakl-brauchsd-ned-nuara-schwimmwestn-do-brauchsd-aaran-schutzengl', 'Auf so aan Schinaakl brauchsd ned nuara Schwimmwestn, do brauchsd aaran Schutzengl!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Auf so einem Schinakel brauchst du nicht nur ''ne Schwimmweste, da brauchst du auch ''nen Schutzengel!', '[{"kategorie": "wörtlich", "text": "\"Auf so einem klapprigen Kahn brauchst du nicht nur ''ne Schwimmweste, da brauchst du auch ''nen Schutzengel!\"  2. \"Auf so einem zusammengebretterten Boot reicht keine Schwimmweste, da brauchst du auch göttlichen Beistand!\"  3. \"Bei so einem Schinakel hilft keine Schwimmweste mehr – da hilft nur beten!\""}]'::jsonb, ''),
  ('fia-soiche-schinaakln-brauchsd-a-weafd-kaa-schuachgschaefd', 'Fia soiche Schinaakln brauchsd a Weafd, kaa Schuachgschäfd!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Für solche Schinakeln brauchst du eine Werft, kein Schuhgeschäft!', '[{"kategorie": "wörtlich", "text": "\"Für solche Riesentreter brauchst du eine Werft, kein Schuhgeschäft!\"  2. \"Für solche [[Rinnsaldampfer]] ist der Schuhhandel nicht zuständig – da brauchst einen Schiffbauer!\"  3. \"Für diese Quadratlatschen brauchst keine Schuhnummer mehr, da brauchst ''nen eigenen Liegeplatz!\""}]'::jsonb, ''),
  ('de-schinaakln-san-so-ausglaatschd-do-hueuefd-kaa-einlog-mea', 'De Schinaakln san so ausglaatschd, do hüüfd kaa Einlog mea!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Die Schinakeln sind so ausgelatscht, da hilft keine Einlage mehr!', '[{"kategorie": "wörtlich", "text": "\"Diese [[Quargeltreter]] sind dermaßen ausgelatscht, da hilft keine Einlage mehr!\"  2. \"Diese [[Rinnsaldampfer]] sind so totgelatscht, da hilft keine Einlage mehr, da hilft nur mehr Entsorgung!\"  3. \"Diese [[Christbaumbrettln]] sind total platt und ausgetreten - da kannst du dir die Einlagen sparen!\""}]'::jsonb, ''),
  ('de-monstbaeck-haum-mea-profueue-ois-a-traktoa', 'De Monstbäck haum mea Profüü ois a Traktoa!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Die Monsterböcke haben mehr Profil als ein Traktor!', '[{"kategorie": "wörtlich", "text": "\"Diese Mammuttreter haben mehr Profil als ein Traktor!\"  2. \"Mit dem Profil dieser Goliath-Treter kannst du ein ganzes Feld umackern!\"  3. \"Mit solchen [[Rinnsaldampfern]] pflügst du jeden Boden beim Gehen frei!\""}]'::jsonb, ''),
  ('de-riisnlaatschn-san-so-plott-und-austreedn-do-kaunnsd-da-de-einloong-schboan', 'De Riisnlaatschn san so plott und austreedn - do kaunnsd da de Einloong schboan!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Diese Riesenlatschen sind so platt und ausgetreten - da kannst du dir die Einlagen sparen!', '[{"kategorie": "wörtlich", "text": "\"Diese Mammuttreter sind total platt und ausgetreten - da kannst du dir die Einlagen sparen!\"  2. \"Diese Goliath-Treter sind ausgetreten bis zur Unkenntlichkeit - die könntest du als Türmatten verwenden!\"  3. \"Diese Rinnsaldampfer sind so durchgetreten - da helfen keine Einlagen mehr, da hilft nur noch der Mistsack!\""}]'::jsonb, ''),
  ('de-riisnlaatschn-san-kaane-fiass-mea-des-san-boodnplottn-mit-zaeaechn', 'De Riisnlaatschn san kaane Fiass mea, des san Boodnplottn mit Zäächn!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Diese Riesenlatschen sind keine Füße mehr, das sind Bodenplatten mit Zehen!', '[{"kategorie": "wörtlich", "text": "\"Diese [[Quadratlatschen]] sind keine Füße mehr, das sind Bodenplatten mit Zehen!\"  2. \"Diese [[Elefantenstampfer]] gehen nicht mehr als Füße durch - das sind Bodenplatten auf Wanderschaft!\"  3. \"Diese [[Rinnsaldampfer]] sind doch keine Füße - das sind Trittplatten mit Zehenaussparung!\""}]'::jsonb, ''),
  ('fia-soiche-rinnsoidaumpfa-is-nimma-da-schuachhaundl-zuaschdaendich-do-brauchsd-an-schiffbaua', 'Fia soiche Rinnsoidaumpfa is nimma da Schuachhaundl zuaschdändich - do brauchsd an Schiffbaua!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Für solche Rinnsaldampfer ist nicht mehr der Schuhhandel zuständig - da brauchst du einen Schiffbauer!', '[{"kategorie": "wörtlich", "text": "\"Für solche Mammuttreter ist nicht mehr der Schuhhandel zuständig - da brauchst du einen Schiffbauer!\"  2. \"Mit solchen [[Schinakeln]] brauchst ''ne Werft, kein Schuhgeschäft!\"  3. \"Bei solchen Goliath-Tretern fragt dich keiner mehr nach der Schuhnummer, sondern nur noch nach’m Tiefgang!\""}]'::jsonb, ''),
  ('des-san-kaane-fiass-mea-des-san-rinnsoidaumpfa-mit-grundbucheintroog', 'Des san kaane Fiass mea, des san Rinnsoidaumpfa mit Grundbucheintroog!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Das sind keine Füße mehr, das sind Rinnsaldampfer mit Grundbucheintrag!', '[{"kategorie": "wörtlich", "text": "\"Das sind keine Füße mehr, das sind [[Riesenlatschen]] mit eigenem Grundbucheintrag!\"  2. \"Für solche Riesenfüße braucht man eigentlich eine eigene Parzelle!\"  3. \"Für diese Elefantenstampfer müsstest du eigentlich Grundsteuer zahlen!\""}]'::jsonb, ''),
  ('waunn-da-rinnsoidaumpfa-von-da-nochbarin-noo-amoi-zua-tia-hiibrunzd-daunn-isa-ausbaanld-und-si-kaunn-si-n-bein-woosnmaasta-oohoin', 'Waunn da Rinnsoidaumpfa von da Nochbarin noo amoi zua Tia hiibrunzd, daunn isa ausbaanld und si kaunn si''n bein Woosnmaasta oohoin!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Wenn der Rinnsaldampfer von der Nachbarin noch einmal zur Tür hinbrunzt, dann ist er ausgebeint und sie kann ihn sich beim Wasenmeister abholen!', '[{"kategorie": "wörtlich", "text": "\"Wenn dieser Mini-Köter meiner Nachbarin noch ein einziges Mal zur Tür hinpinkelt, wird er entbeint und dem [[Wasenmeister]] übergeben!\"  2. \"Wenn dieser Rollmops mit Leine noch einmal an meine Tür pinkelt, schneid ich ihm die Knochen raus und übergeb'' ihn an den Wasenmeister!\"  3. \"Noch ein Urinspritzer an meiner Tür, und der Nachbarsdackel wird ausgebeint und der Tierkörperverwertung übergeben!\""}]'::jsonb, ''),
  ('mit-seine-grissbaambreedln-bleibda-aun-an-jeedn-tiaschdock-haenga', 'Mit seine Grissbaambreedln bleibda aun an jeedn Tiaschdock hänga!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Mit seinen Christbaumbrettern bleibt er an jedem Türstock hängen!', '[{"kategorie": "wörtlich", "text": "\"Mit seinen Christbaumlatten bleibt er an jedem Türstock hängen!\"  2. \"Mit seinen [[Elferhaxen]] verkeilt er sich in jedem Türstock!\"  3. \"Seine Riesenfüße sind wie Türkeile - die verklemmen sich unter jeder Türzarge!\""}]'::jsonb, ''),
  ('des-san-kaane-schuach-mea-des-san-grissbaambreedln-mit-schniabandln', 'Des san kaane Schuach mea, des san Grissbaambreedln mit Schniabandln!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Das sind keine Schuhe mehr, das sind Christbaumbretter mit Schnürbändern!', '[{"kategorie": "wörtlich", "text": "\"Das sind keine Schuhe, das sind Christbaumlatten mit Schnürsenkeln!\"  2. \"Für solche Christbaumlatten ist nicht mehr der Schuhhandel zuständig - da brauchst du einen Zimmermann!  3. \"Mit solchen [[Rinnsaldampfern]] pflügt er jeden Boden beim Gehen frei!\""}]'::jsonb, ''),
  ('seit-mi-s-schlaagl-gschdraafd-hod-haengd-ma-de-goschn-owe', 'Seit mi s''Schlaagl gschdraafd hod, hängd ma de Goschn owe!', '', '', '', 'Krank & kuriert auf Wienerisch', 'Seit mich das Schlagerl gestreift hat, hängt mir die Gosch''n runter!', '[{"kategorie": "wörtlich", "text": "\"Seit ich einen leichten Schlaganfall hatte, hängt mir der Mund schief runter!\"  2. \"Seit dem leichten Schlaganfall ist mein Lächeln etwas nach unten verrutscht!\"  3. \"Ein leichter Schlaganfall - und jetzt hängt mir ein Mundwinkel runter wie nach einer durchzechten Nacht!\""}]'::jsonb, ''),
  ('sii-hod-a-schlaagal-ghobt', 'Sii hod a Schlaagal ghobt!', '', '', '', 'Krank & kuriert auf Wienerisch', 'Sie hat ein Schlagerl gehabt!', '[{"kategorie": "wörtlich", "text": "\"Sie hatte einen leichten Schlaganfall!\"  2. \"Sie erlitt einen milden Schlaganfall!\"  3. [[Ihr]] hat es das Hirn leicht gekitzelt!  4. Ihr hat es das Hirn leicht angestupst!"}]'::jsonb, ''),
  ('waunn-di-a-schlaagl-darennd-hauts-da-von-an-moment-aufn-aundan-in-schdecka-ausse', 'Waunn di a Schlaagl darennd, hauts da von an Moment aufn aundan in Schdecka ausse!', '', '', '', 'Krank & kuriert auf Wienerisch', 'Wenn dich ein Schlagl derrennt, haut''s dir von einem Moment auf den anderen den Stecker raus!', '[{"kategorie": "wörtlich", "text": "\"Wenn dich ein Schlaganfall ereilt, reißt es dir von einem Moment auf den anderen den Stecker raus!\"  2. \"Trifft dich ein Schlaganfall, zieht dir das Leben schlagartig den Stecker!\"  3. \"Wenn der Schlaganfall zuschlägt, geht von jetzt auf gleich alles offline!\""}]'::jsonb, ''),
  ('seitn-hiankitzla-reedt-a-wiara-radio-mit-wooglkontakt', 'Seitn Hiankitzla reedt a wiara Radio mit Wooglkontakt!', '', '', '', 'Krank & kuriert auf Wienerisch', 'Seit dem Hirnkitzler redet er wie ein Radio mit Wackelkontakt!', '[{"kategorie": "wörtlich", "text": "\"Seit seinem Schlaganfall redet er wie ein Radio mit Wackelkontakt!\"  2. \"Seit er einen leichten Schlaganfall hatte, redet er wie ein lautsprecher mit Kabelbruch!\"  3. \"Seit es ihm das Hirn leicht gekitzelt hat, redet er wie ein alter Kassettenrekorder mit Bandsalat und leerer Batterie!\""}]'::jsonb, ''),
  ('a-hianschubsa-is-ungefaea-so-wia-waunns-da-im-hian-kuaz-a-sicharung-aussehaud', 'A Hianschubsa is ungefäa so, wia waunns da im Hian kuaz a Sicharung aussehaud!', '', '', '', 'Krank & kuriert auf Wienerisch', 'Ein Hirnschubser ist ungefähr so, wie wenn''s dir im Hirn kurz eine Sicherung raushaut!', '[{"kategorie": "wörtlich", "text": "\"Ein leichter Schlaganfall ist ungefähr so, als würd'' dir im Hirn kurz der Strom ausfallen!\"  2. \"Ein [[Hirnkitzler]] fühlt sich an wie ein vorübergehender Kurzschluss im Oberstübchen!\"  3. \"Ein Hirnschubser – und im Hirn fliegt dir kurz die Sicherung!\""}]'::jsonb, ''),
  ('ia-hods-hian-leichd-kitzld', 'Ia hods Hian leichd kitzld!', '', '', '', 'Krank & kuriert auf Wienerisch', 'Ihr hat es das Hirn leicht gekitzelt!', '[{"kategorie": "wörtlich", "text": "\"Sie hatte einen leichten Schlaganfall!\"  2. \"Sie erlitt einen milden Schlaganfall!\"  3. \"Ein kleiner [[Hirnkitzler]], mehr war’s nicht!\"  4. [[Ihr hat es das Hirn leicht angestupst!]]"}]'::jsonb, ''),
  ('ia-hods-hian-leichd-augschubst', 'Ia hods Hian leichd augschubst!', '', '', '', 'Krank & kuriert auf Wienerisch', 'Ihr hat es das Hirn leicht angeschubst!', '[{"kategorie": "wörtlich", "text": "\"Sie hatte einen leichten Schlaganfall!\"  2. \"Sie erlitt einen milden Schlaganfall!\"  3. \"Ein kleiner [[Hirnstupser]], mehr war’s nicht!\"  4. [[Ihr hat es das Hirn leicht gekitzelt!]]"}]'::jsonb, ''),
  ('a-schlogoowashauwal-auf-an-doppaedn-mokka-is-wia-a-kiaschn-auf-da-tuatn', 'A Schlogoowashauwal auf an doppädn Mokka is wia a Kiaschn auf da Tuatn!', '', '', '', 'Wiener Kaffeehaus-ABC', 'Ein Schlagobershäubchen auf ''nem doppelten Mokka ist wie die Kirsche auf der Torte!', '[{"kategorie": "wörtlich", "text": "\"Ein Sahnehäubchen auf ''nem doppelten Espresso ist wie die Kirsche auf der Torte!\"  2. \"Ein Schlagobershäubchen auf ''nem doppelten Mokka ist das kleine Extra, das alles rund macht!\"  3. \"Ein [[Schlagobersgupf]] auf einem großen [[Schwarzen]] ist das Tüpfelchen auf dem i!\""}]'::jsonb, ''),
  ('ois-schlogoowashauwal-hod-ma-da-schaeaef-aa-noo-a-gehoidseahoehung-geebm', 'Ois Schlogoowashauwal hod ma da Schääf aa noo a Gehoidseahöhung geebm!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Als Schlagobershäubchen hat mir der Chef auch noch eine Gehaltserhöhung gegeben!', '[{"kategorie": "wörtlich", "text": "\"Als Draufgabe hat mir der Chef auch noch mein Gehalt erhöht!\"  2. \"Als Krönung obendrauf gab’s vom Chef auch noch ''ne Gehaltserhöhung!\"  3. \"Als [[Zuckerl]] erhielt ich zusätzlich auch noch ''ne Gehaltserhöhung!\""}]'::jsonb, ''),
  ('i-sauf-no-an-kloarn-den-siichd-de-leewa-ned', 'I sauf no an Kloarn - den siichd de Leewa ned!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Ich saufe noch einen Klaren - den sieht die Leber nicht!', '[{"kategorie": "wörtlich", "text": "\"Ein Klarer geht noch - der ist für die Leber unsichtbar!\"  2. \"Ich nehm noch einen Kurzen, der rinnt unentdeckt durch die Leber!\"  3. \"Noch ein Schnaps kann nicht schaden - aber bitte einen Klaren, den bemerkt die Leber nicht!\""}]'::jsonb, ''),
  ('im-kaff-kennd-si-a-jeeda-de-schlaumpn-woa-wiakli-schoo-mit-oin-im-bett', 'Im Kaff kennd si a jeeda - de Schlaumpn woa wiakli schoo mit oin im Bett!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Im Kaff kennt sie jeder — die Schlampe war wirklich schon mit allen im Bett!', '[{"kategorie": "wörtlich", "text": "\"Hier im Kaff ist sie berüchtigt — diese Schlampe war echt schon mit jedem im Bett!\"  2. \"Im Nest hier gilt sie als Dorfmatratze – kein Wunder, dieses Flittchen tingelt von Bett zu Bett!\"  3. \"Dieses Luder wird hier rumgereicht wie ein Wanderpokal - die Schlampe hat bestimmt keinen ausgelassen!\""}]'::jsonb, ''),
  ('hoit-de-goschn-du-oeloeoendiche-schlaumpn', 'Hoit de Goschn, du ölööndiche Schlaumpn!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Halt die Gosch''n, du elendige Schlampe!', '[{"kategorie": "wörtlich", "text": "\"Halt die Fresse, du elendes Drecksstück!\"  2. \"Maul halten, du widerliche Schlampe!\"  3. \"Halt endlich die Klappe, du dreckiges Luder!\""}]'::jsonb, ''),
  ('mit-da-schlaumpnschleidan-foad-si-de-kistn-echt-schwaummich', 'Mit da Schlaumpnschleidan foad si de Kistn echt schwaummich!', '', '', '', 'Wiener Mechaniker-Slang', 'Mit der Schlampenschleuder fährt sich die Kiste echt schwammig!', '[{"kategorie": "wörtlich", "text": "\"Mit dem Soziussitz hinten drauf fährt sich das Motorrad echt schwammig!\"  2. \"Mit dem Beifahrersitz fährt sich das Eisen wie Pudding!\"  3. \"Mit dem Zusatzsitz hinten drauf gerät das Fahrwerk ins Schwimmen!\""}]'::jsonb, ''),
  ('mit-so-an-schlaumpal-kaunnsd-ned-zsaummleebm-uadnung-is-fia-de-a-fremdwuat', 'Mit so an Schlaumpal kaunnsd ned zsaummleebm - Uadnung is fia de a Fremdwuat!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Mit so einem Schlamperl kannst nicht zusammenleben - Ordnung ist für die ein Fremdwort!', '[{"kategorie": "wörtlich", "text": "\"Mit diesem Schmutzlieschen hältst du’s keine Woche aus – Ordnung ist für die ein Fremdwort!\"  2. \"Mit so einem Messie-Mädel bist du verloren, die kennt keine Ordnung!\"  3. \"Mit diesem Schlamperl hältst du’s keine Woche aus – bei der herrscht Dauerchaos!\""}]'::jsonb, ''),
  ('si-is-a-klaans-schlampal-treusein-is-ia-genauso-fremd-wia-uadnung-im-leebm', 'Si is a klaans Schlampal - Treusein is ia genauso fremd wia Uadnung im Leebm!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Sie ist ein kleines Schlamperl - Treusein ist ihr genauso fremd wie Ordnung im Leben!', '[{"kategorie": "wörtlich", "text": "\"Sie ist ein kleines Flittchen  - die kennt weder Treue noch Ordnung!\"  2. \"Sie ist halt ein kleines Luder – nie treu, und aufgeräumt schon gar nicht!\"  3. \"Sie ist ein Schlamperl durch und druch – Treue kennt sie nur vom Hörensagen, Ordnung gar nicht!\""}]'::jsonb, ''),
  ('de-rennd-so-schlaumpad-umanaund-ois-waarads-ia-egal-wias-ausschaud', 'De rennd so schlaumpad umanaund, ois waarads ia egal, wias ausschaud!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Die rennt so schlampert herum, als wär''s ihr egal, wie sie aussdchaut!', '[{"kategorie": "wörtlich", "text": "\"Die läuft so ungepflegt herum, als wär''s ihr egal, wie sie aussieht!\"  2. \"Die läuft so verlottert herum, als wäre ihr das eigene Äußere egal!\"  3. \"Sie wirkt so schmuddelig, als hätte sie sich selbst aufgegeben!\""}]'::jsonb, ''),
  ('des-is-schlaumpad-montiad-de-schraufn-san-nua-hoiwad-drin-und-aane-foeoed-gaunz', 'Des is schlaumpad montiad - de Schraufn san nua hoiwad drin, und aane fööd gaunz!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Das ist schlampert montiert - die Schrauben sind nur halb drin, und eine fehlt ganz!', '[{"kategorie": "wörtlich", "text": "\"Das ist viel zu nachlässig montiert - die Schrauben sind nur halb drin, und eine fehlt ganz!\"  2. \"Das ist montiert wie hingeschissen – Schrauben nur halb drin, eine ganz vergessen!\"  3. \"Das ist unsachgemäß montiert – Schrauben nur handwarm, eine fehlt komplett!\""}]'::jsonb, ''),
  ('des-is-ned-schlaumpad', 'Des is ned schlaumpad!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Das ist nicht schlampert!', '[{"kategorie": "wörtlich", "text": "\"Das ist nicht ohne!\"  2. \"Das ist nicht von schlechten Eltern!\"  3. \"Das hat es in sich!\"  4. \"Das ist kein Pappenstiel!\"  5. [[Des is kaa Bemmal!]]"}]'::jsonb, 'Des is kaa Hund!'),
  ('a-schlaumpads-vahoeoetnis', 'a schlaumpads Vahöötnis', '', '', '', 'Wiener Sprüche, die sitzen!', 'ein schlampertes Verhältnis', '[{"kategorie": "wörtlich", "text": "\"eine lockere Beziehung\""}, {"kategorie": "", "text": "\"eine unstete On/Off-Beziehung\""}, {"kategorie": "", "text": "\"eine lose Liebesbeziehung\""}]'::jsonb, 'Des zwischn ia und mia woara schlaumpads Vahöötnis - a On/Off-Beziihung hoid!'),
  ('des-zwischn-ia-und-mia-woara-schlaumpads-vahoeoetnis-a-on-off-beziihung-hoid', 'Des zwischn ia und mia woara schlaumpads Vahöötnis - a On/Off-Beziihung hoid!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Das zwischen ihr und mir war ein schlampiges Verhältnis - eine On/Off-Beziehung halt!', '[{"kategorie": "wörtlich", "text": "\"Das zwischen ihr und mir war ein ständiges Hin und Her - eine lose, unstete Beziehung halt!\"  2. \"Das zwischen mir und ihr war eine lockere Liebesbeziehung - mal zusammen, mal getrennt!\"  3. \"Das zwischen ihr und mir war eine Achterbahnbeziehung - ein ständiges On-off!\""}]'::jsonb, 'a schlaumpads Vahöötnis'),
  ('des-is-so-a-schlaumpadoodsch-dea-lossd-ollas-liing-und-schdee-von-dreckade-sockn-bis-zu-laeaeare-kaffeehaeaefaln', 'Des is so a Schlaumpadoodsch, dea lossd ollas liing und schdee - von dreckade Sockn bis zu lääare Kaffeehääfaln!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Das ist so ein Schlampertatsch, der lässt alles liegen und stehen - von dreckigen Socken bis zu leeren Kaffeehäferln!', '[{"kategorie": "wörtlich", "text": "\"Der Kerl ist ein solcher Schludrian, der alles herumkugeln lässt – von schmutzigen Socken bis zum leeren Kaffeehäferl!\"  2. \"Das ist so ein Saubär, der räumt nichts weg - weder dreckige Socken noch leere Kaffeeschalen!\"  3. \"Der Typ ist ein echter Messie - bei dem stapelt sich das Leben am Boden, von schmutzigen Socken bis hin zu leeren Kaffeeschalen!\""}]'::jsonb, ''),
  ('dea-schlaumpsock-lossd-sein-dreck-iwaroi-liing-und-daunn-wundad-a-si-aa-noo-warums-iwaro-faeud', 'Dea Schlaumpsock lossd sein Dreck iwaroi liing - und daunn wundad a si aa noo, warums iwaro fäud!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Dieser Schlampsack lässt seinen Dreck überall liegen -  und dann wundert er sich auch noch, warum''s überall fäult!', '[{"kategorie": "wörtlich", "text": "\"Dieser Saubär lässt seinen Dreck überall liegen -  und dann wundert er sich auch noch, warum''s überall stinkt!\"  2. \"Dieser schlampige Drecksack verteilt seinen Mist überall und fragt sich danach ernsthaft, warum alles fault!\"  3. \"Dieser Saustallbewohner lebt wie ein Schwein, lässt seinen Dreck liegen und ist dann überrascht, dass es überall gammelt!\""}]'::jsonb, ''),
  ('waunnsd-dera-an-schlissl-gibsd-kaunnsd-sicha-sei-dass-eam-vaschlaumpd', 'Waunnsd dera an Schlissl gibsd, kaunnsd sicha sei, dass eam vaschlaumpd!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Wenn du der einen Schlüssel gibst, kannst du sicher sein, dass sie ihn verschlampt!', '[{"kategorie": "wörtlich", "text": "\"Wenn du dieser Frau einen Schlüssel gibst, verlegt sie ihn sicher irgendwo!\"  2. \"Gib ihr einen Schlüssel, und sie verbummelt den fix!\"  3. \"Man sollte ihr besser keinen Schlüssel anvertrauen, denn sie baut ihn sicher irgendwo an!\""}]'::jsonb, ''),
  ('dea-hod-sei-buudn-so-vaschlaumpd-dass-jetzd-iwaroi-nua-noo-schimmaed-und-faeud', 'Dea hod sei Buudn so vaschlaumpd, dass jetzd iwaroi nua noo schimmäd und fäud!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der hat seine Bude so verschlampt, dass es jetzt überall nur noch schimmelt und fäult!', '[{"kategorie": "wörtlich", "text": "\"Der hat seine Wohnung derart versaut, dass es jetzt überall nur noch gammelt und stinkt!\"  2. \"Er hat die eigene Bude komplett vergammeln lassen - die ist zu einem regelrechten Schimmelbiotop verkommen!\"  3. \"Seine Wohnung ist total versifft und vergammelt - überall nur noch Schimmel und Gestank!\""}]'::jsonb, ''),
  ('des-flitschal-is-a-beidlnarrischa-fickfetzn-de-lossd-nix-und-neamd-aus', 'Des Flitschal is a beidlnarrischa Fickfetzn - de lossd nix und neamd aus!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Dieses Flitscherl ist ein beidlnarrischer Fickfetzen - die lässt nichts und niemanden aus!', '[{"kategorie": "wörtlich", "text": "\"Dieses Flittchen ist ein schwanzfixiertes Fickobjekt - die treibt''s mit allen und jedem!\"  2. \"Dieses Schlamperl ist als Fickunterlage bekannt - die ist verrückt nach Schwänzen!\"  3. \"Dieses mannstolle Weib nennt man nur noch ''Fickfetzen''  - die macht für jeden die Beine breit!\""}]'::jsonb, ''),
  ('du-beidlnarrischa-fickfetzn', 'Du beidlnarrischa Fickfetzn!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Du beidlnarrischer Fickfetzen!', '[{"kategorie": "wörtlich", "text": "\"Du schwanzfixiertes Fickobjekt!\"  2. \"Du schwanzverrückte Fickunterlage!\"  3. \"Du mannstolles, verficktes Weibsbild!\""}]'::jsonb, ''),
  ('den-sei-oide-is-a-notoorische-duafmatrotzn-auf-dera-is-schoo-a-jeeda-moi-gleeng-und-hod-schbaass-ghobd', 'Den sei Oide is a notoorische Duafmatrotzn - auf dera is schoo a jeeda moi gleeng und hod Schbaass ghobd!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Die Alte von ihm ist eine notorische Dorfmatratze - auf der ist schon jeder mal gelegen und hat Spaß gehabt!', '[{"kategorie": "wörtlich", "text": "\"Seine Alte ist ''ne echte Dorfmatratze – auf der war wirklich schon jeder mal drauf!\"  2. \"Seine Alte ist als Dorfmatratze bekannt – bei der war schon jeder mal zugange!\"  3. \"Er ist jetzt mit dieser Dorfmatratze zusammen - ein Wanderpokal, der so oft rumgereicht worden ist, dass sie wirklich jeder kennt!\""}]'::jsonb, ''),
  ('waunn-dea-a-fuassboimaetsch-schaud-hoda-schdaendig-in-schlapfn-offn', 'Waunn dea a Fuassboimätsch schaud, hoda schdändig in Schlapfn offn!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Wenn der ein Fußballmatch schaut, hat er ständig den Schlapfen offen!', '[{"kategorie": "wörtlich", "text": "\"Wenn der ein Fußballmatch schaut, hat er ständig die Klappe offen!\"  2. Wenn der Kerl Fußball schaut, kann er einfach nicht die Fresse halten!  3. Der hat beim Fußball immer den Mund offen und gibt zu jedem Pass seinen Senf dazu!"}]'::jsonb, ''),
  ('meina-oidn-kummd-kaana-mit-schdroossnschuach-ins-haus-bei-dera-muass-si-jeeda-schoo-auf-da-tiadackn-de-schlapfn-auziang', 'Meina Oidn kummd kaana mit Schdroossnschuach ins Haus - bei dera muass si jeeda schoo auf da Tiadackn de Schlapfn auziang!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Meiner Alten kommt keiner mit Straßenschuhen ins Haus - bei ihr muss sich jeder schon auf der Türdacken die Schlapfen anziehen!', '[{"kategorie": "wörtlich", "text": "\"Meiner Frau kommt keiner mit Straßenschuhen ins Haus - bei ihr muss sich jeder schon auf der Türmatte die Hauspantoffeln anziehen!\"  2. Meiner Frau kommt keiner mit Straßenschuhen ins Haus – bei ihr bekommt jeder sofort Hauspatschen, sobald er auf der Türmatte steht!  3. Bei meiner Frau musst du in Pantoffel schlüpfen, bevor du überhaupt „Grüß Gott“ sagen darfst!"}]'::jsonb, ''),
  ('bevua-i-ma-so-an-schlapfn-ind-kuchl-schdoeoe-koch-i-liawa-soeoewa', 'Bevua I ma so an Schlapfn ind Kuchl schdöö, koch I liawa sööwa!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Bevor ich mir so einen Schlapfen in die Küche stelle, koch ich lieber selber!', '[{"kategorie": "wörtlich", "text": "\"Bevor ich mir so eine Trulla in die Küche stelle, koch ich lieber selber!\"  2. Bevor ich ein derart nutzloses Weib anstelle, koche ich lieber selber!  3. Bevor ich mir so eine Schnalle in die Küche hole, schneid ich meine Zwiebeln lieber selbst!"}]'::jsonb, ''),
  ('dea-hod-heit-echt-a-feins-fussal-mit-de-neichn-schlapfn-spueueda-wiara-fuassboigott', 'Dea hod heit echt a feins Fussal - mit de neichn Schlapfn spüüda wiara Fuassboigott!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Der hat heute echt ein feines Füßchen – mit den neuen Schlapfen spielt er wie ein Fußballgott!', '[{"kategorie": "wörtlich", "text": "\"Der hat heute echt ein feines Füßchen – mit den neuen Stoppelschuhen spielt er wie ein Fußballgott!\"  2. Der hat heute echt einen Zauberfuß – die neuen Fußballschuhe zahlen sich voll aus!  3. Mit den neuen Kickschuhen ist er kaum zu halten – richtig feines Füßchen!"}]'::jsonb, ''),
  ('hoid-jetzt-amoi-dein-schlapfn', 'Hoid jetzt amoi dein Schlapfn!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Halte jetzt einmal deinen Schlapfen!', '[{"kategorie": "wörtlich", "text": "\"Halt jetzt einmal deine Klappe!\"  2. Jetzt halt doch endlich die Schnauze!  3. Halt jetzt einmal deine [[Goschen]]!"}]'::jsonb, ''),
  ('de-schlapfn-ausschdreckn', 'de Schlapfn ausschdreckn', '', '', '', 'Tod und Sterben auf Wienerisch', 'die Schlapfen ausstrecken', '[{"kategorie": "wörtlich", "text": "\"die Schlappen ausstrecken\""}, {"kategorie": "scherzhaft für", "text": "\"das Zeitliche segnen\""}, {"kategorie": "", "text": "[[die]] Patschen strecken"}, {"kategorie": "", "text": "[[ein]] Bankerl reißen"}, {"kategorie": "", "text": "[[ins]] Gras beißen"}, {"kategorie": "", "text": "[[den]] Löffel abgeben"}, {"kategorie": "", "text": "[[sich]] die Erdäpfel von unten anschauen"}]'::jsonb, 'Waunn I amoi de Schlapfn ausschdreck, sois wenigstns schnöö gee!'),
  ('waunn-i-amoi-de-schlapfn-ausschdreck-sois-wenigstns-schnoeoe-gee', 'Waunn I amoi de Schlapfn ausschdreck, sois wenigstns schnöö gee!', '', '', '', 'Tod und Sterben auf Wienerisch', 'Wenn ich einmal die Schlapfen ausstreck'', soll’s wenigstens schnell gehen!', '[{"kategorie": "wörtlich", "text": "\"Wenn ich mal das Zeitliche segne, soll’s wenigstens schnell gehen!\"  2. Wenn ich mal den Löffel abgebe, soll''s bitte schnell gehen!  3. Wenn ich mal abkratze, soll’s hoffentlich fix gehen!"}]'::jsonb, 'de Schlapfn ausschdreckn'),
  ('dem-traepfaed-beim-reedn-pausnlos-da-schlatz-aus-da-goschn', 'Dem träpfäd beim Reedn pausnlos da Schlatz aus da Goschn!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Dem tröpfelt beim Reden pausenlos der Schlatz aus der Goschen!', '[{"kategorie": "wörtlich", "text": "\"Dem tröpfelt beim Reden pausenlos der Speichel aus dem Mund!\"  2. Der trenzt beim Reden wie ein alter Wasserhahn!  3. Mit jedem Wort, das er sagt, rinnt ihm mehr Speichel aus dem Mund!"}]'::jsonb, ''),
  ('auf-meine-schuach-pickd-no-da-feichde-schlatz', 'Auf meine Schuach pickd no da feichde Schlatz!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Auf meinen Schuhen pickt noch der feuchte Schlatz!', '[{"kategorie": "wörtlich", "text": "\"An meinen Schuhen klebt noch der feuchte Schlamm!\"  2. Meine Schuhe sind noch voller nassem Schmutz!  3. Meine Latschen sind bis obenhin mit Morast eingesaut!  4. Da klebt noch Gülle an meinen Sohlen!"}]'::jsonb, ''),
  ('sei-schlatzka-pickd-no-imma-aum-fenstarauman', 'Sei Schlatzka pickd no imma aum Fenstarauman!', '', '', '', 'Wiener Gaunersprache', 'Sein Schlatzker pickt noch immer am Fensterrahmen!', '[{"kategorie": "wörtlich", "text": "\"Sein Spuckbatzen klebt noch immer am Fensterrahmen!\"  2. Sein Spuckklumpen klebt immer noch am Fensterrahmen wie festgewachsen!  3. Seine Spuckreste zieren noch immer den Fensterrahmen!"}]'::jsonb, ''),
  ('wos-do-ausn-toschntiachl-kumma-is-woa-mea-schlatzig-ois-fest-fost-scho-lebendig', 'Wos do ausn Toschntiachl kumma is, woa mea schlatzig ois fest - fost scho lebendig!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Was da aus dem Taschentuch gekommen ist, war mehr schlatzig als fest – fast schon lebendig!', '[{"kategorie": "wörtlich", "text": "\"Was da aus dem Taschentuch gekommen ist, war mehr glitschig als fest – fast schon lebendig!\"  2. \"Was da aus dem Taschentuch gekommen ist, war eher schleimig als fest – fast schon lebendig!\"  3. \"Der Taschentuchinhalt war so glibberig - der hat fast noch geatmet – ich schwör’s!\""}]'::jsonb, ''),
  ('dea-schlatzd-hii-zum-kiiwara-und-wundad-si-dass-eam-oofian', 'Dea schlatzd hii zum Kiiwara und wundad si, dass eam oofian!', '', '', '', 'Wiener Gaunersprache', 'Der schlatzt hin zum Kieberer und wundert sich, dass sie ihn abführen!', '[{"kategorie": "wörtlich", "text": "\"Der rotzt zum Kieberer hin und wundert sich, dass sie ihn einkassieren!\"  2. \"Der spuckt in Richtung des Bullen und wundert sich, dass sie ihn in Handschellen abführen!\"  3. \"Er schlatzt hin zum Polizisten und fragt nachher, warum er abgeführt wird!\""}]'::jsonb, ''),
  ('des-schaud-aus-wia-hiigschlatzd', 'Des schaud aus wia hiigschlatzd!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Das sieht aus wie hingeschlatzt!', '[{"kategorie": "", "text": "Das sieht aus wie hingerotzt!  2. Das sieht total schlampig aus!  3. Das sieht aus wie hingeklatscht!"}]'::jsonb, ''),
  ('da-gschnitzde-haud-gean-iwad-schleich', 'Da Gschnitzde haud gean iwad Schleich!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Der Geschnitzte haut gerne über die Schläuche!', '[{"kategorie": "Fußballerjargon, wörtlich", "text": "\"Der rustikale Abwehrrecke tritt gerne mal gegen die Beine!\"  2. Dieser knallharte Verteidiger lässt die Gegner gern mal seine Stollen spüren!  3. Dieser kompromisslose Verteidiger teilt gerne mal ordentlich aus!"}]'::jsonb, ''),
  ('da-gschnitzde-do-hintn-draad-si-laungsauma-ois-a-kreizfoatschiff', 'Da Gschnitzde do hintn draad si laungsauma ois a Kreizfoatschiff!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Der Geschnitzte da hinten dreht sich langsamer als ein Kreuzfahrtschiff!', '[{"kategorie": "wörtlich", "text": "\"Der Holzklotz da hinten dreht sich langsamer als ein Kreuzfahrtschiff!\"  2. Das ist kein Verteidiger, das ist ein unbeweglicher Holzklotz - der dreht sich ja langsamer als der Mannschaftsbus in der 30er-Zone!  3. So einen unbeweglichen Standfußballer hab ich noch nie erlebt - bis sich der umdreht, ist Halbzeit!"}]'::jsonb, ''),
  ('da-hoizgschnitzde-do-hintn-draad-si-laungsauma-ois-a-kreizfoatschiff', 'Da Hoizgschnitzde do hintn draad si laungsauma ois a Kreizfoatschiff!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Der Holzgeschnitzte da hinten dreht sich langsamer als ein Kreuzfahrtschiff!', '[{"kategorie": "wörtlich", "text": "\"Der Holzklotz da hinten dreht sich langsamer als ein Kreuzfahrtschiff!\"  2. Das ist kein Verteidiger, das ist ein unbeweglicher Holzklotz - der dreht sich ja langsamer als der Mannschaftsbus in der 30er-Zone!  3. So einen unbeweglichen Standfußballer hab ich noch nie erlebt - bis sich der umdreht, ist Halbzeit!"}]'::jsonb, ''),
  ('da-hoizgschnitzde-haud-gean-iwad-schleich', 'Da Hoizgschnitzde haud gean iwad Schleich!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Der Holzgeschnitzte haut gerne über die Schläuche!', '[{"kategorie": "Fußballerjargon, wörtlich", "text": "\"Der rustikale Abwehrrecke tritt gerne mal gegen die Beine!\"  2. Dieser knallharte Verteidiger lässt die Gegner gern mal seine Stollen spüren!  3. Dieser kompromisslose Verteidiger teilt gerne mal ordentlich aus!"}]'::jsonb, 'wem iwad Schleich haun'),
  ('si-schleichn', 'si schleichn', '', '', '', 'Grundwortschatz Wienerisch', 'sich schleichen', '[{"kategorie": "wörtlich", "text": "\"sich leise fortbewegen\" (vom mittelhochdeutschen \"slīchen\"=\"gleiten\")"}, {"kategorie": "allg.", "text": "sich davonschleichen, sich leise davonmachen, das Weite suchen, sich aus dem Staub machen"}]'::jsonb, 'Kaunnst leise gee? Daunn schleich di!'),
  ('schleich-di', 'Schleich di!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Schleich dich!', '[{"kategorie": "wörtlich", "text": "\"Hau ab!\"  2. Verschwinde!  3. Zieh Leine!  4. [[Vazupf]] di!  4. [[Putz]] di!  5. Draa di!  6. [[Hau]] di in Rettich!  7. [[Moch]] Määta!  8. [[Gee]] päule!"}]'::jsonb, ''),
  ('na-gee', 'Na gee!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Na geh!', '[{"kategorie": "wörtlich, (Ausruf des Erstaunens", "text": "\"Na sowas!\";  \"Echt jetzt?\";  \"Im Ernst?\";  \"Was du nicht sagst!\";  \"Darf das wahr sein?\";  \"Ist ja nicht zu glauben!\";  \"Das gibt''s doch nicht!\";  \"Ist ja nicht möglich!\";  \"Unglaublich!\""}, {"kategorie": "Ausruf des Bedauerns", "text": "\"Oje!\";  Ach herrje!\";  \"Oh nein!\";  \"Na servus!\";  \"So ein Pech!\";  \"Wie blöd!\""}, {"kategorie": "Ausruf des Protests/Tadels", "text": "\"Also bitte, ...\";  \"Sag mal, ...\";  \"Also ehrlich, ...\";  \"Also wirklich, ..."}]'::jsonb, 'Na gee, hod des wiakli sei miassn?'),
  ('na-gee-des-hoda-wiakli-gsoogd', 'Na gee, des hoda wiakli gsoogd?', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Na geh, das hat er wirklich gesagt?', '[{"kategorie": "wörtlich", "text": "\"Echt jetzt? Das hat er wirklich gesagt?\"  2. \"Im Ernst, das waren seine Worte?\"  3. \"Na sowas, das hat er wirklich gesagt?\""}]'::jsonb, 'Na gee!'),
  ('na-gee-hod-des-wiakli-sei-miassn', 'Na gee, hod des wiakli sei miassn?', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Na geh, hat das wirklich sein müssen?', '[{"kategorie": "wörtlich", "text": "\"Also bitte, hat das wirklich sein müssen?\"  2. \"Sag mal, warum denn das Ganze?\"  3. \"Also ehrlich, das hätt’s jetzt echt nicht gebraucht!\""}]'::jsonb, 'Na gee!'),
  ('na-gee-wia-isn-des-passiad', 'Na gee, wia isn des passiad?', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Na geh, wie ist denn das passiert?', '[{"kategorie": "wörtlich", "text": "\"Ach herrje, wie ist denn das passiert?\"  2. \"So ein Pech, wie kam''s denn dazu?\"  3. \"Oh nein, wie konnte das loß passieren?\""}]'::jsonb, 'Na gee!'),
  ('na-gee-hea-auf', 'Na gee, hea auf!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Na geh, hör auf!', '[{"kategorie": "wörtlich, Ausruf des Erstaunens", "text": "\" Na sowas, unglaublich!\"  2. \"Echt jetzt? Ist ja nicht zu glauben!\" 3. \"Was du nicht sagst! Das gibt''s doch nicht!\""}]'::jsonb, ''),
